#pragma once
#include "PatternTools.h"
static void testPatternTools(const File& root,Assets& assets){
    auto source=emptyProject();source.bpm=120;source.loop=false;source.songMode=true;source.patterns[0].name="Together";source.patterns[0].lanes[0]={{0,.25,36,.7f,.8f,2},{2,.25,38,.6f}};source.patterns[0].lanes[7]={{.13,.7,60,.8f},{2,1,67,.6f,.6f,3}};
    auto second=source.patterns[0];second.name="Other layer";second.length=4;for(auto& lane:second.lanes)lane.clear();second.lanes[7]={{1,.5,64,.7f}};source.patterns.push_back(second);source.clips={{0,0,0,8},{7,0,0,16},{7,0,16,8},{1,0,4,4},{7,1,24,4}};
    source.markers={{"part-a","Opening",0,8,2}};source.loopSection="part-a";auto before=JSON::toString(projectToJson(source));Project output;PatternEditStats stats;
    expect(makeClipPatternUnique(source,1,output,&stats).wasOk()&&output.patterns.size()==3&&stats.created==std::vector<int>{2}&&stats.relinked==1,"Make unique creates exactly one pattern and relinks exactly one clip");
    expect(output.clips[1].pattern==2&&output.clips[0].pattern==0&&output.clips[2].pattern==0&&output.clips[1].length==16&&output.clips[1].track==7,"Make unique preserves other links, clip lane and repeated-instance length");
    expect(output.patterns[2].lanes==source.patterns[0].lanes&&output.patterns[2].length==8&&output.activePattern==2,"unique pattern copies all channels and original note articulation exactly");
    expect(JSON::toString(projectToJson(source))==before,"pattern operations never mutate their const source");
    auto audioBefore=render(source,assets,root,90000,127),audioUnique=render(output,assets,root,90000,512);float difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<90000;++i)difference=jmax(difference,std::abs(audioBefore.getSample(ch,i)-audioUnique.getSample(ch,i)));expect(difference<.000001f&&audioBefore.getMagnitude(0,0,90000)>.001f,"Make unique preserves actual Song audio across callback sizes");
    output.patterns[2].lanes[7][0].pitch=72;expect(output.patterns[0].lanes[7][0].pitch==60&&source.patterns[0].lanes[7][0].pitch==60,"editing unique notes cannot change originals or another shared instance");
    auto mixed=source;Clip audio{2,999,1,2};audio.audioPath="local-source.wav";audio.sourceOffset=.2;audio.gain=.3f;audio.fadeIn=.25;mixed.clips.push_back(audio);Clip automation{2,0,1,2};automation.automationTarget=0;automation.automationTrack=7;automation.points={{0,.2f,false},{2,.7f,true}};mixed.clips.push_back(automation);
    expect(splitPatternChannels(mixed,0,output,&stats).wasOk()&&output.patterns.size()==4&&stats.created==std::vector<int>{2,3}&&stats.relinked==3,"Split creates one pattern per populated channel and relinks matching instances");
    expect(output.clips[0].pattern==2&&output.clips[1].pattern==3&&output.clips[2].pattern==3&&output.clips[3].pattern==0&&output.clips[4].pattern==1,"Split uses clip channel identity and retains silent-lane and unrelated references");
    expect(output.clips[5].audioPath==audio.audioPath&&output.clips[5].pattern==999&&output.clips[5].sourceOffset==.2&&output.clips[5].gain==.3f&&output.clips[6].pattern==0&&output.clips[6].points.size()==2&&output.clips[6].automationTrack==7,"Split leaves audio sources, trims, fades and automation references untouched");
    expect(output.patterns[2].lanes[0]==source.patterns[0].lanes[0]&&output.patterns[2].lanes[7].empty()&&output.patterns[3].lanes[7]==source.patterns[0].lanes[7]&&output.patterns[3].lanes[0].empty(),"split patterns contain only their original channel notes");
    expect(output.patterns[0].lanes==source.patterns[0].lanes&&output.patterns[0].length==8&&output.loopSection==source.loopSection&&output.markers[0].id=="part-a","Split retains original source, marker identity and linked section selection");
    splitPatternChannels(source,0,output);auto audioSplit=render(output,assets,root,90000,511);difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<90000;++i)difference=jmax(difference,std::abs(audioBefore.getSample(ch,i)-audioSplit.getSample(ch,i)));expect(difference<.000001f,"Split and Playlist relinking preserve exact audible Song output");
    auto sentinel=JSON::toString(projectToJson(output));stats={{17},19};expect(splitPatternChannels(source,1,output,&stats).failed()&&JSON::toString(projectToJson(output))==sentinel&&stats.created==std::vector<int>{17}&&stats.relinked==19,"already separated pattern fails without partial output or stats changes");
    auto empty=source;for(auto& lane:empty.patterns[0].lanes)lane.clear();expect(splitPatternChannels(empty,0,output).failed(),"empty pattern split does not waste pattern slots");
    expect(makeClipPatternUnique(mixed,5,output).failed()&&makeClipPatternUnique(mixed,6,output).failed(),"Make unique rejects audio and automation clips explicitly");expect(makeClipPatternUnique(source,-1,output).failed()&&makeClipPatternUnique(source,100,output).failed(),"Make unique rejects stale clip selection");
    auto limited=source;while(limited.patterns.size()<30)limited.patterns.push_back(second);expect(splitPatternChannels(limited,0,output).wasOk()&&output.patterns.size()==32,"Split accepts exactly the 32-pattern capacity");limited.patterns.push_back(second);sentinel=JSON::toString(projectToJson(output));expect(splitPatternChannels(limited,0,output).failed()&&JSON::toString(projectToJson(output))==sentinel,"insufficient split slots fail atomically before any clip relink");limited.patterns.push_back(second);expect(makeClipPatternUnique(limited,1,output).failed()&&mergePatternLayers(limited,0,1,output).failed(),"unique and merge refuse a full pattern bank");
    expect(mergePatternLayers(source,0,1,output,&stats).wasOk()&&output.patterns.size()==3&&output.patterns[2].length==8&&stats.created==std::vector<int>{2}&&stats.relinked==0,"Merge creates a new pattern using the longer source length");
    const auto& merged=output.patterns[2];expect(merged.lanes[0]==source.patterns[0].lanes[0]&&merged.lanes[7].size()==3&&merged.lanes[7][0]==source.patterns[0].lanes[7][0]&&merged.lanes[7].back()==second.lanes[7][0],"Merge overlays one pass without looping, quantizing, deduplicating or changing articulation");
    expect(JSON::toString(projectToJson(output)["clips"])==JSON::toString(projectToJson(source)["clips"])&&output.patterns[0].lanes==source.patterns[0].lanes&&output.patterns[1].lanes==second.lanes,"Merge leaves both source patterns and all Playlist clips unchanged");
    auto reference=source;reference.songMode=false;reference.patterns[0].lanes[7].push_back(second.lanes[7][0]);output.songMode=false;auto manual=render(reference,assets,root,90000,512),layered=render(output,assets,root,90000,127);difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<90000;++i)difference=jmax(difference,std::abs(manual.getSample(ch,i)-layered.getSample(ch,i)));expect(difference<.000001f,"merged Pattern audio matches a manually layered reference");
    sentinel=JSON::toString(projectToJson(output));expect(mergePatternLayers(source,0,0,output).failed()&&mergePatternLayers(source,0,99,output).failed()&&JSON::toString(projectToJson(output))==sentinel,"self or stale merge selection cannot change output");
    auto dense=source;dense.patterns[0].lanes[7].assign(256,Note{0,.1,60,.8f});dense.patterns[1].lanes[7].assign(256,Note{1,.1,64,.8f});expect(mergePatternLayers(dense,0,1,output).wasOk()&&output.patterns.back().lanes[7].size()==512,"Merge permits exactly 512 notes in one channel");dense.patterns[1].lanes[7].push_back({2,.1,67,.8f});sentinel=JSON::toString(projectToJson(output));expect(mergePatternLayers(dense,0,1,output).failed()&&JSON::toString(projectToJson(output))==sentinel,"oversized merged lane rejects the whole operation");
    auto bad=source;bad.clips[0].pattern=55;expect(splitPatternChannels(bad,0,output).failed(),"malformed unrelated Playlist references cannot pass through a pattern edit");bad=source;bad.patterns[0].lanes.pop_back();expect(makeClipPatternUnique(bad,1,output).failed(),"pattern lane-count mismatch is rejected before copying");bad=source;bad.patterns[0].lanes[0][0].beat=std::numeric_limits<double>::quiet_NaN();expect(splitPatternChannels(bad,0,output).failed(),"nonfinite source notes are rejected without mutation");
    auto names=source;names.patterns[0].name=String::repeatedString("A",80);names.tracks[0].name="Same";names.tracks[7].name="Same";splitPatternChannels(names,0,output);expect(output.patterns[2].name.length()<=80&&output.patterns[3].name.length()<=80&&!output.patterns[2].name.equalsIgnoreCase(output.patterns[3].name)&&!output.patterns[2].name.equalsIgnoreCase(output.patterns[0].name),"long and colliding source/channel names yield bounded unique pattern names");
    auto inPlace=source;expect(makeClipPatternUnique(inPlace,1,inPlace).wasOk()&&inPlace.patterns.size()==3&&inPlace.clips[1].pattern==2,"pattern operations support a source/output alias safely");
    splitPatternChannels(source,0,output);Project loaded;expect(projectFromJson(projectToJson(output),loaded).wasOk()&&loaded.patterns[3].lanes==output.patterns[3].lanes&&loaded.clips[1].pattern==3&&(int)projectToJson(output)["schema"]==projectSchema,"split patterns and clip links roundtrip in unchanged current project schema");
}
